INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(85,'livenation_tw','livenation_tw:event-a_root-%E5%90%8C%E6%A0%B9%E7%94%9F%E5%8D%81%E9%80%B1%E5%B9%B4%E6%97%97%E8%89%A6%E5%B0%88%E5%A0%B4-%E7%A5%9E%E9%81%8A-loading--taipei-tickets-edp1668900','organizer_announcement','A_Root 同根生十週年旗艦專場《神遊》Loading⋯','https://www.livenation.com.tw/event/a_root-%E5%90%8C%E6%A0%B9%E7%94%9F%E5%8D%81%E9%80%B1%E5%B9%B4%E6%97%97%E8%89%A6%E5%B0%88%E5%A0%B4-%E7%A5%9E%E9%81%8A-loading--taipei-tickets-edp1668900','2026-07-29T16:00:00.000Z',NULL,NULL,'Live Nation Taiwan','可購買票券 General Onsale 拓元售票系統 全面開賣 一般售票 拓元售票系統 全面開賣 - 一般售票 活動內容 A_Root 同根生十週年旗艦專場《神遊》Loading⋯ 我做得費神，你聽得入神 半夜裡傷神，想辦法安神 屏氣凝神，不再恍神，造自己的神 ⸻ 「神遊」是一種狀態 有時候是創作時的走神 在夢幻泡影中逐步解題 有時候是生活裡的放空 在混沌現實裡短暫離線 在這裡 你會抽離一下日常 重新整理自己的位置 再想像接下來的人生 一起浪漫遁逃，加載完成繼續遊戲人間。 A_Root 同根生，來自2016年臺灣宜蘭。以民族樂器為根，融合流行與電子聲響，在神話與民俗之間回應當代焦慮，並透過多語創作建構獨特聲音世界。曾獲金曲獎與多項音樂獎肯定，並受邀登上巴黎文化奧運、墨西哥塞萬提斯藝術節等國際舞台。成團十年，從民俗到電子、從土地到鬼神，濃縮成獨特世界觀。 A_Root 同根生十週年旗艦專場《神遊》Loading⋯ ● 時間：2026/7/30 19:00進場，20:00開演 ● 地點：Legacy Taipei ● 票價：限量VIP $2,400元 / 一般站區 $1,400元 ✦ 關於限量VIP套票：包含站區門票一張、VIP掛繩和吊牌一組、優先入場，肯夢AVEDA x A_Root同根生大禮包、《神遊》週邊神秘禮*2、演出結束後優先拍照等，完整詳情請至拓元售票頁面。 ➤➤2026/4/29 中午12點 拓元售票系統 全面開賣➤➤ ※ 實際時間請以現場公告為準 ※ 拓元售票系統為官方唯一授權購票平台 ※ 入場須配合安檢及入場須知 ※ 以上活動內容，主辦單位 Live Nation Taiwan 保留異動之權力 ※ 協辦單位：笙根蘭陽、創銘實業股份有限公司、環球國際唱片股份有限公司 ※ 贊助單位：肯夢AVEDA、先進國樂 SENJIN MUSIC、杰隆印刷 ①本公司為尊重他人音樂著作財產權，秉持事先授權原則，承諾於所舉辦之演唱會演出前向權利人申請合法授權 ②本場演出所使用音樂將向MÜST取得授權 本活動藝人名稱 主要表演者 A_Root同根生 Share','可購買票券 General Onsale 拓元售票系統 全面開賣 一般售票 拓元售票系統 全面開賣 - 一般售票 活動內容 A_Root 同根生十週年旗艦專場《神遊》Loading⋯ 我做得費神，你聽得入神 半夜裡傷神，想辦法安神 屏氣凝神，不再恍神，造自己的神 ⸻ 「神遊」是一種狀態 有時候是創作時的走神 在夢幻泡影中逐步解題 有時候是生活裡的放空 在混沌現實裡短暫離線 在這裡 你會抽離一下日常 重新整理自己的位置 再想像接下來的人生 一起浪漫遁逃，加載完成繼續遊戲人間。 A_Root 同根生，來自2016年臺灣宜蘭。