INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(151,'ticketplus','721ad470d2693a922d4975b3003c1cda','ticket_platform','TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI','https://ticketplus.com.tw/activity/721ad470d2693a922d4975b3003c1cda','2026-07-03T16:00:00.000Z','Zepp New Taipei',NULL,'好玩專賣店 / 大國文化','TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI Zepp New Taipei 新北市新莊區新北大道四段 3 號 8 樓 好玩專賣店 / 大國文化 若信用卡刷卡付款失敗，會將刷卡失敗的訂單，陸續轉為【ATM虛擬帳號付款】，屆時請依"我的訂單"顯示之「銀行帳號」、「銀行代碼」於「匯款期限」內完成付款，系統將以款項實際入帳時間為準，請於繳費後一小時至"我的訂單"確認，若訂單付款狀態顯示為「待繳費」，須等待銀行回傳付款狀態；若逾期未付款，系統收到銀行回傳付款狀態後將自動取消該筆訂單並顯示「付款失敗」，各家銀行轉帳入帳時間不同，請盡早繳款以保障您的權益。 ※ 請留意【ATM虛擬帳號付款】匯款期限為15分鐘。 ※ 刷卡付款失敗時，訂單將自動轉為【ATM虛擬帳號付款】；若尚未顯示ATM虛擬帳號，請重整訂單頁面。 睽違 7 年！日本極致美學代表 TK from 凜冽時雨 2026 台北開唱 神曲〈unravel〉Spotify 破四億大關 7/4 登陸 Zepp New Taipei 震撼感官 讓台灣樂迷苦等七年的漫長歲月，在日本樂壇中象徵著「純粹與狂氣並存」、擁有藝術家靈魂的指標性人物——搖滾樂團「凜冽時雨」主唱 TK 的個人企劃「TK from 凜冽時雨」，終於正式宣布登陸台灣！最新巡演「TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI」將於 2026 年 7 月 4 日（週六）隆重登場。這場意義非凡的個人專場公演，必將為台灣樂迷帶來一場震撼靈魂的至高饗宴。 TK (TK from Ling tosite sigure)的音樂生涯正值巔峰。其為動畫《東京喰種》演唱的傳奇神曲〈unravel〉，在 Spotify 上的串流播放次數已正式突破 4 億大關，展現跨越國界的超高影響力。除了經典神曲，《鏈鋸人》片尾曲：〈first death〉、《我的英雄學院》第七季片頭曲：〈誰我為〉、《我獨自升級》片尾曲：〈UN-APEX〉等等，也都是台灣歌迷耳熟能詳的作品。今年TK(TK from Ling tosite sigure)更與知名團體 MYTH & ROID 展開「夢幻聯動」，受邀獻唱人氣動畫 《Re:從零開始的異世界生活》第四季 片尾曲〈Ender Ember〉。TK(TK from Ling tosite sigure) 以其極具辨識度的纖細唱腔與充滿爆發力的編曲，再度於全球動漫界與樂壇引爆話題。 TK (TK from Ling tosite sigure)即將展開的 2026 北美洲巡迴演出展現出勢如破竹的熱度，包含舊金山、洛杉磯、紐約等指標城市皆接連傳出 SOLD OUT 捷報。緊接在北美洲公演之後，這股音樂風暴將轉向亞洲。TK (TK from Ling tosite sigure)以淒美動人的嗓音、狂放的吉他技巧與精緻複雜的編曲著稱，現場公演更因其強烈的情緒張力被譽為「必須進場親身體驗的藝術品」。此次台北演唱會是睽違 7 年的驚喜再會，絕對不容錯過。 【演出資訊】 演出名稱： TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI 演出日期： 2026 年 7 月 4 日（六）16：30 OPEN / 18：00 START 演出地點： Zepp New Taipei 主辦單位： 好玩專賣店、大國文化 票價：1F A區 NT 2,800 / 1F B區 NT 2,500 / 2F 座位區 NT 2,800 / 身障區 NT $1,250 售票時間：2026/5/10（日）11:00 AM ※ 【1F A區】、【1F B區】皆為站位區。 ※ 本次站位區將依票面序號整隊入場，站位之入場序號於售票系統上請以「位置」之號碼為準，票面上請以「座位」之號碼為準。 ※ 票券若有消費者未結帳或退票，空出之號碼有可能會被比較晚買的消費者購買，亦可能同筆訂單會有不連號情形發生。 ※ 詳細整隊、入場資訊請留意後續主辦粉絲專頁相關公告。 TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI 2026-07-04 ~ 2026-07-04 18:00 ~ 18:00 Zepp New Taipei 新北市新莊區新北大道四段 3 號 8 樓 2026-04-30T11:38:00+08:00 一般票 NT$2800 exposeStart 2026-04-30T11:38:00+08:00 exposeEnd 2026-07-05T00:00:00+08:00 一般票 NT$2500 exposeStart 2026-04-30T11:38:00+08:00 exposeEnd 2026-07-05T00:00:00+08:00 一般票 NT$2800 exposeStart 2026-04-30T11:38:00+08:00 exposeEnd 2026-07-05T00:00:00+08:00 身障票 NT$1250 exposeStart 2026-04-30T11:38:00+08:00 exposeEnd 2026-07-05T00:00:00+08:00','TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI Zepp New Taipei 新北市新莊區新北大道四段 3 號 8 樓 好玩專賣店 / 大國文化 若信用卡刷卡付款失敗，會將刷卡失敗的訂單，陸續轉為【ATM虛擬帳號付款】，屆時請依"我的訂單"顯示之「銀行帳號」、「銀行代碼」於「匯款期限」內完成付款，系統將以款項實際入帳時間為準，請於繳費後一小時至"我的訂單"確認，若訂單付款狀態顯示為「待繳費」，須等待銀行回傳付款狀態；若逾期未付款，系統收到銀行回傳付款狀態後將自動取消該筆訂單並顯示「付款失敗」，各家銀行轉帳入帳時間不同，請盡早繳款以保障您的權益。 ※ 請留意【ATM虛擬帳號付款】匯款期限為15分鐘。 ※ 刷卡付款失敗時，訂單將自動轉為【ATM虛擬帳號付款】；若尚未顯示ATM虛擬帳號，請重整訂單頁面。 睽違 7 年！日本極致美學代表 TK from 凜冽時雨 2026 台北開唱 神曲〈unravel〉Spotify 破四億大關 7/4 登陸 Zepp New Taipei 震撼感官 讓台灣樂迷苦等七年的漫長歲月，在日本樂壇中象徵著「純粹與狂氣並存」、擁有藝術家靈魂的指標性人物——搖滾樂團「凜冽時雨」主唱 TK 的個人企劃「TK from 凜冽時雨」，終於正式宣布登陸台灣！最新巡演「TK from Ling tosite sigure ASIA TOUR 2026 in TAIPEI」將於 2026 年 7 月 4 日（週六）隆重登場。這場意義非凡的個人專場公演，必將為台灣樂迷帶來一場震撼靈魂的至高饗宴。 TK (TK from Ling tosite sigure)的音樂生涯正值巔峰。其為動畫《東京喰種》演唱的傳奇神曲〈unravel〉，在 Spotify 上的串流播放次數已正式突破 4 億大關，展現跨越國界的超高影響力。除了經典神曲，《鏈鋸人》片尾曲：〈first death〉、《我的英雄學院》第七季片頭曲：〈誰我為〉、《我獨自升級》片尾曲：〈UN-APEX〉等等，也都是台灣歌迷耳熟能詳的作品。今年TK(TK from Ling tosite sigure)更與知名團體 MYTH & ROID 展開「夢幻聯動」，受邀獻唱人氣動畫 《Re:從零開始的異世界生活》第四季 片尾曲〈Ender Ember〉。TK(TK from Ling tosite sigure) 以其極具辨識度的纖細唱腔與充滿爆發力的編曲，再度於全球動漫界與樂壇引爆話題。 TK (TK from Ling tosite sigure)即將展開的 2026 北美洲巡迴演出展現出勢如破竹的熱度，包含舊金山、洛杉磯、紐約等指標城市皆接連傳出 SOLD OUT 捷報。緊接在北美洲公演之後，這股音樂風暴將轉向亞洲。