INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(188,'ticketplus','68bf41e935407b2c628124ae4a83ce7f','ticket_platform','CHIIKAWA DAYS 台北特展（一般全票）','https://ticketplus.com.tw/activity/68bf41e935407b2c628124ae4a83ce7f','2026-07-03T16:00:00.000Z','華山1914文創園區 東2館四連棟',NULL,'OMOLABO','CHIIKAWA DAYS 台北特展（一般全票） 華山1914文創園區 東2館四連棟 100台北市中正區八德路一段1號 OMOLABO CHIIKAWA DAYS 台北特展（特典套票）點此購買 若信用卡刷卡付款失敗，會將刷卡失敗的訂單，陸續轉為【ATM虛擬帳號付款】，屆時請依"我的訂單"顯示之「銀行帳號」、「銀行代碼」於「匯款期限」內完成付款，系統將以款項實際入帳時間為準，請於繳費後一小時至"我的訂單"確認，若訂單付款狀態顯示為「待繳費」，須等待銀行回傳付款狀態；若逾期未付款，系統收到銀行回傳付款狀態後將自動取消該筆訂單並顯示「付款失敗」，各家銀行轉帳入帳時間不同，請盡早繳款以保障您的權益。 ※ 請留意【ATM虛擬帳號付款】匯款期限為60分鐘。 ※ 刷卡付款失敗時，訂單將自動轉為【ATM虛擬帳號付款】；若尚未顯示ATM虛擬帳號，請重整訂單頁面。 去年由香港創意品牌AllRightsReserved主辦、 風靡香港的吉伊卡哇大型特展「CHIIKAWA DAYS」正式登台！「CHIIKAWA DAYS 台北特展」由OMOLABO主辦，並與協力夥伴Spiralcute、AllRightsReserved攜手呈獻，將於7/4至9/27在華山1914文創園區盛大開展！本次台北站不只規模比照香港特展，同步引進互動裝置提升沉浸感，更特別設計全新「台灣夜市」主題展區及周邊商品，帶來最有台味的吉伊卡哇體驗！特展採售票制與預約入場。 CHIIKAWA DAYS台北特展 活動日期：2026.7.4(六) - 9.27(日) 營業時間： ・7/4(六)〜7/31(五) 每日10:00-19:00（18:20最後入場） ・8/1(六)〜9/27(六) 每日11:00-19:00（18:20最後入場） 活動地點：華山1914文創園區 東2館四連棟（台北市中正區八德路一段1號） 票價：特典套票 NTD1580 / 一般全票 NTD490 / 優待票 NTD470 / 愛心票 NTD245 「吉伊卡哇的可愛全日常」 從「衣」、「食」、「住」、「行」到日常小冒險——走進吉伊卡哇的世界、挑戰討伐任務，還有全新登場的台灣限定「夜市」空間，滿滿驚喜等你發掘！展覽呈現多個經典場景，包括：網咖、「郎」拉麵、監獄、三星餐廳及「討伐名場面」等。 親身探索，沉浸互動體驗： 展區中埋藏多個互動裝置，持有特典套票的粉絲可以舉起專屬的「討伐棒」觸發展場內的影像聲光效果，不只用眼睛看，還能親自體驗與吉伊卡哇、小八貓和兔兔一起踏上日常冒險之旅！ 「台灣夜市」全新主題，最有台味的在地體驗： 台北站加碼推出全新「台灣夜市」限定系列，該系列將在展覽中化身成專區展品與限定周邊，是本次展覽的最大亮點之一。 CHIIKAWA DAYS 台北特展（一般全票） 2026-07-04 ~ 2026-09-27 11:00 ~ 19:00 華山1914文創園區 東2館四連棟 100台北市中正區八德路一段1號 2026-06-05T12:45:00+08:00 一般全票 NT$490 exposeStart 2026-06-05T12:45:00+08:00 exposeEnd 2026-09-28T00:00:00+08:00','CHIIKAWA DAYS 台北特展（一般全票） 華山1914文創園區 東2館四連棟 100台北市中正區八德路一段1號 OMOLABO CHIIKAW