INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(259,'indievox','26_iv0406510','ticket_platform','2026 The Next Big Thing 大團誕生（開發場3）','https://www.indievox.com/activity/detail/26_iv0406510','2026-07-01T16:00:00.000Z','Legacy Taipei 音樂展演空間（台北市八德路一段1號 台北華山創意園區 中五館）',NULL,'應聲倒地、越野快餐車、過敏症候群','EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 2026 The Next Big Thing 大團誕生（開發場3） 立即購票 節目介紹 注意事項 演出日期及時間：2026/07/02 (四) 20:00 演出地點：Legacy Taipei 音樂展演空間（台北市八德路一段1號 台北華山創意園區 中五館） 演出者：應聲倒地、越野快餐車、過敏症候群 票價：盲著買票 17 元 / 預售單人票 300 元 / 預售雙人套票 500 元 / 預售四人套票 900 元 / 現場票 350 元 / 身障票 150 元（線上購票） 售票時間：2026/05/18（一）12:00 開始販售 只有我的床單 大得像一艘船 我沒有目的地的 航向那片大海 我相信 這世界絕對不會虧待我 我就這樣一直走 頭也不回地往前走 跟著我 青春剩下幾秒鐘 走那條單行的道路 讓我成為一本暢銷書 地平線之後 未來正在等著我 應聲倒地 On the Floor 應聲倒地成立於2023年，以 indie rock 為底，青春但沒有橫衝直撞跟太多惆悵，通過自由且沒有框架的方式，分享心中最真實的感受。 先後於台北及台中 SOLD OUT 首張EP《耳東有爾 Near Your Ear》發片場，2026 應聲倒地將帶著新作品前往各大音樂節和活動，探索更多從未見過的風景。 越野快餐車 Wild Fast Food 越野快餐車成立於 2023 年的台北，曲風受到搖滾、放克與獨立搖滾影響，創作融合躁動的節奏與直率情緒，透過強烈且高張力的現場能量，讓聽眾在吵雜而瞬息萬變的現代生活中，尋找內心的真實與自由。 過敏症候群 The Allergics 過敏症候群是由主唱陳竑宇與工作室中學習爵士鼓的同門學生張惟碩於2024年中組成的雙人極簡編制樂團。樂團創作以搖滾和電子為基底，撚入post punk\synthpop的風格，在快速旋轉的世界中尋找屬於他們的聲音。 2025 年末，兩人正式將團名定為「過敏症候群」。對於早期創作階段的情感，他們將成團至今的所思所想整理成歌，以 EP 名稱的方式保留「Demo 症候群」的名字，記錄生活的種種「過敏反應」。儘管對於生活偶爾迷惘，偶爾碰撞，仍希望用堅定的口穩訴說生活中的故事。 ※本平台所售出之活動，除非特別標示，皆無提供履約保障機制。 ※購買票券前，請先了解並同意以上規範，如不同意請勿購買，以免產生不必要之糾紛及損害；當進行購票及退票作業時，將視同您已瞭解並同意遵守以上全部事項。 以下為外部廣告網站，與本公司無關，請審慎點擊廣告連結 以上為外部廣告網站，與本公司無關，請審慎點擊廣告連結 | 關於iNDIEVOX | 會員服務條款 | 隱私權政策 | Cookie 偏好設定 | 票務服務單位：一定發股份有限公司／統一編號53550756 客服專線：+886 (02) 8772-6205 客服時間：週一 ~ 週五 13:30-18:00 (適逢國定假日暫停服務) 客服信箱：support@indievox.com © iNDIEVOX 版權所有 當您按下"接受所有 Cookie"，表示您同意我們使用 Cookie 的方式。我們使用 Cookie 以提昇本系統的服務品質、提供個人化內容和廣告、分析使用狀況以協助我們進行行銷工作。 接受所有 Cookie 全部拒絕 Cookie 設定','EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 2026 The Next Big Thing 大團誕生（開發場3） 立即購票 節目介紹 注意事項 演出日期及時間：2026/07/02 (四) 20:00 演出地點：Legacy Taipei 音樂展演空間（台北市八德路一段1號 台北華山創意園區 中五館） 演出者：應聲倒地、越野快餐車、過敏症候群 票價：盲著買票 17 元 / 預售單人票 300 元 / 預售雙人套票 500 元 / 預售四人套票 900 元 / 現場票 350 元 / 身障票 150 元（線上購票） 售票時間：2026/05/18（一）12:00 開始販售 只有我的床單 大得像一艘船 我沒有目的地的 航向那片大海 我相信 這世界絕對不會虧待我 我就這樣一直走 頭也不回地往前走 跟著我 青春剩下幾秒鐘 走那條單行的道路 讓我成為一本暢銷書 地平線之後 未來正在等著我 應聲倒地 On the Floor 應聲倒地成立於2023年，以 indie rock 為底，青春但沒有橫衝直撞跟太多惆悵，通過自由且沒有框架的方式，分享心中最真實的感受。 先後於台北及台中 SOLD OUT 首張EP《耳東有爾 Near Your Ear》發片場，2026 應聲倒地將帶著新作品前往各大音樂節和活動，探索更多從未見過的風景。 越野快餐車 Wild Fast Food 越野快餐車成立於 2023 年的台北，曲風受到搖滾、放克與獨立搖滾影響，創作融合躁動的節奏與直率情緒，透過強烈且高張力的現場能量，讓聽眾在吵雜而瞬息萬變的現代生活中，尋找內心的真實與自由。 過敏症候群 The Allergics 過敏症候群是由主唱陳竑宇與工作室中學習爵士鼓的同門學生張惟碩於2024年中組成的雙人極簡編制樂團。樂團創作以搖滾和電子為基底，撚入post punk\synthpop的風格，在快速旋轉的世界中尋找屬於他們的聲音。 2025 年末，兩人正式將團名定為「過敏症候群」。對於早期創作階段的情感，他們將成團至今的所思所想整理成歌，以 EP 名稱的方式保留「Demo 症候群」的名字，記錄生活的種種「過敏反應」。儘管對於生活偶爾迷惘，偶爾碰撞，仍希望用堅定的口穩訴說生活中的故事。 ※本平台所售出之活動，除非特別標示，皆無提供履約保障機制。 ※購買票券前，請先了解並同意以上規範，如不同意請勿購買，以免產生不必要之糾紛及損害；當進行購票及退票作業時，將視同您已瞭解並同意遵守以上全部事項。 以下為外部廣告網站，與本公司無關，請審慎點擊廣告連結 以上為外部廣告網站，與本公司無關，請審慎點擊廣告連結 | 關於iNDIEVOX | 會員服務條款 | 隱私權政策 | Cookie 偏好設定 | 票務服務單位：一定發股份有限公司／統一編號53550756 客服專線：+886 (02) 8772-6205 客服時間：週一 ~ 週五 13:30-18:00 (適逢國定假日暫停服務) 客服信箱：support@indievox.com © iNDIEVOX 版權所有 當您按下"接受所有 Cookie"，表示您同意我們使用 Cookie 的方式。我們使用 Cookie 以提昇本系統的服務品質、提供個人化內容和廣告、分析使用狀況以協助我們進行行銷工作。 接受所有 Cookie 全部拒絕 Cookie 設定','pending',0.45,'','','2026-06-18T08:14:15.458Z',NULL,'2026-06-18T08:14:26.178Z','2026-06-18T08:14:26.154Z','[]','{}','','legacy');
