INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(477,'livenation_tw','livenation_tw:event-%E5%9B%9E%E8%81%B2%E6%A8%82%E5%9C%98-%E9%9D%88%E9%AD%82%E7%9A%84%E5%9B%9E%E8%81%B2%E5%B0%88%E8%BC%AF%E9%A6%96%E6%BC%94-taipei-tickets-edp1679287','organizer_announcement','回聲樂團：靈魂的回聲專輯首演','https://www.livenation.com.tw/event/%E5%9B%9E%E8%81%B2%E6%A8%82%E5%9C%98-%E9%9D%88%E9%AD%82%E7%9A%84%E5%9B%9E%E8%81%B2%E5%B0%88%E8%BC%AF%E9%A6%96%E6%BC%94-taipei-tickets-edp1679287','2026-08-28T16:00:00.000Z',NULL,NULL,'Live Nation Taiwan','可購買票券 General Onsale 全面開賣 一般售票 全面開賣 - 一般售票 活動內容 回聲樂團：靈魂的回聲專輯首演 8.29 Legacy Taipei 我想回到 19 歲，那個在新竹 Live 酒吧隨口說出團名的夜晚， 對那個年輕的自己說：「你們準備好踏上一條不歸路了嗎？」 Echo of Your Soul——靈魂的回聲 它不只是一個團名 而是關於音樂為何存在的探索之旅 台灣獨立搖滾指標樂團 回聲樂團 Echo of Your Soul 2026 全新錄音室專輯《靈魂的回聲》 睽違多年的完整創作回歸 跨越時空與物理維度的「末日浪漫主義」 離開舞台的那幾年，回聲樂團的成員各自走向截然不同的人生。主唱柏蒼持續在台灣獨立音樂產業深耕創業；吉他手尹均研發出新型吉他拆裝專利；貝斯手小邱成為「邱個」，在運動產業闖出名號；鍵盤手 Shipy 決定讓孩子們親眼看見台上發光的樣子；鼓手春佑婚後移居台南，直到在「浪人祭」的限定演出中，台下樂迷的熱情沒有散去，反而在這些年裡悄悄積累成一股巨大的能量，春佑感受到，還有未竟的創作，還有未說完的話，於是她再次集結所有人。 《靈魂的回聲》，是回聲樂團回歸後的第一張完整成績單，十首歌全部來自重聚之後的新創作。英倫搖滾與華麗搖滾的美學仍刻在樂團的骨子裡：柏蒼優雅而充滿戲劇張力的歌聲，帶著 T-Rex 與 Bowie 的騷氣；尹均的吉他在音牆與英雄式獨奏之間切換，時而讓人想起 Radiohead，時而又有 L''Arc〜en〜Ciel 的戲劇色彩。而這一次，專輯的音樂元素比過往任何一張都更豐富，卻又更合而為一。 只要繼續唱著，我們就知道那個靈魂的回聲還在 _ 8月29日 Legacy Taipei 與所有等待已久的人一起 繼續探索音樂 回聲樂團：靈魂的回聲專輯首演 時間：2026/8/29（六） 地點：Legacy Taipei 票價：NT$1,280 / 身障優惠票 NT$640 ➤ 全面開賣 2026/6/9 12PM 拓元售票系統 ※ 實際演出時間請以現場公告為準。請務必於演出日前至Live Nation Taiwan官方平台詳讀活動入場須知及相關流程，以免損害權益 ※ 請注意拓元售票系統為官方唯一授權購票平台。 ※ 入場須配合安檢及入場須知 ※ 以上活動內容，主辦單位Live Nation Taiwan保留異動之權力 ①本公司為尊重他人音樂著作財產權，秉持事先授權原則，承諾於所舉辦之演唱會演出前向權利人申請合法授權。 ②本場演出所使用音樂將向MÜST取得授權。 本活動藝人名稱 主要表演者 回聲樂團 Echo of Your Soul Share','可購買票券 General Onsale 全面開賣 一般售票 全面開賣 - 一般售票 活動內容 回聲樂團：靈魂的回聲專輯首演 8.29 Legac