INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(793,'indievox','26_iv04100e2','ticket_platform','7/12(日) 狀態疊加 VOL.1','https://www.indievox.com/activity/detail/26_iv04100e2','2026-07-11T16:00:00.000Z','迴響音樂藝文展演空間',NULL,NULL,'EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 7/12(日) 狀態疊加 VOL.1 立即購票 節目介紹 注意事項 7/12（Sun.) 狀態疊加vol.1 粒子在被觀測前，是以所有可能性同時存在。 音樂是純粹的能量，在這個疊加的空間裡，無需定義也沒有定義，只有定義自己 主體性沒有公式，舞台是一種大型實驗，這是——觀測和表達自我的答案 小貓這次不被觀測。他是觀看者、也是被觀看者 貓咪的世界裡他「創造」 這是，跳脫敘述的實驗🧪！ ——-- 演出陣容： 無邊境日常Unlimited Life 以龐克為基底。社會上籠罩了許多扭曲的價值觀，但這並不代表人生只能有特定的道路，每個人都有許多可能，鼓勵大家能夠在乏味的日子尋找屬於自己的無邊境日常。 凌晨出走Dawn Drift 四個大學生、自台北組成、樂風是獨立搖滾，擅長從日常的細微感受出發，將自我投射進音樂當中，寫給那些停留在相同心情的人。 丑人MUMMER 不是因為真的醜，而是不願假裝。 活在真相之前，有時顯得不堪，但我們寧願如此。 來自台中的三人樂團。作品有歌詞，也有不靠文字敘述的器樂演奏音樂。用旋律與聲音，記錄與世界的摩擦、與自己的拔河。在越來越追求精緻與完美的年代，我們仍然相信，讓人起雞皮疙瘩的，很多時候不是完美，而是真實。寫給平凡卻不肯被磨平的靈魂。 ———— 🐈‍⬛演出資訊 📆日期與時間：7.12（Sun.) 20:00入場；20:30開演 🧫演出地點：迴響音樂藝文展演空間 🎙️演出陣容：無邊境日常Unlimited Life、凌晨出走Dawn Drift、丑人MUMMER 💿票價：ADV（預售）$400；DOOR（現場）$500 🌀穿隧入口：iNDIEVOX網站 及 全國7-11 ibon系統 *** 本場館全面禁帶外食、敬請見諒 ※本節目由活動主辦建檔上架 ※本平台所售出之活動，除非特別標示，皆無提供履約保障機制。 ※購買票券前，請先了解並同意以上規範，如不同意請勿購買，以免產生不必要之糾紛及損害；當進行購票及退票作業時，將視同您已瞭解並同意遵守以上全部事項。 以下為外部廣告網站，與本公司無關，請審慎點擊廣告連結 深入瞭解 音樂與音訊 音樂 音樂會 嘻哈音樂 音樂活動 節目資訊 獨立音樂 訂單查詢 演唱會門票 現場演出 以上為外部廣告網站，與本公司無關，請審慎點擊廣告連結 | 關於iNDIEVOX | 會員服務條款 | 隱私權政策 | Cookie 偏好設定 | 票務服務單位：一定發股份有限公司／統一編號53550756 客服專線：+886 (02) 8772-6205 客服時間：週一 ~ 週五 13:30-18:00 (適逢國定假日暫停服務) 客服信箱：support@indievox.com © iNDIEVOX 版權所有 當您按下"接受所有 Cookie"，表示您同意我們使用 Cookie 的方式。我們使用 Cookie 以提昇本系統的服務品質、提供個人化內容和廣告、分析使用狀況以協助我們進行行銷工作。 接受所有 Cookie 全部拒絕 Cookie 設定','EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 7/12(日) 狀態疊加 VOL.1 立即購票 節目介紹 注意事項 7/12（Sun.) 狀態疊加vol.1 粒子在被觀測前，是以所有可能性同時存在。 音樂是純粹的能量，在這個疊加的空間裡，無需定義也沒有定義，只有定義自己 主體性沒有公式，舞台是一種大型實驗，這是——觀測和表達自我的答案 小貓這次不被觀測。他是觀看者、也是被觀看者 貓咪的世界裡他「創造」 這是，跳脫敘述的實驗🧪！ ——-- 演出陣容： 無邊境日常Unlimited Life 以龐克為基底。社會上籠罩了許多扭曲的價值觀，但這並不代表人生只能有特定的道路，每個人都有許多可能，鼓勵大家能夠在乏味的日子尋找屬於自己的無邊境日常。 凌晨出走Dawn Drift 四個大學生、自台北組成、樂風是獨立搖滾，擅長從日常的細微感受出發，將自我投射進音樂當中，寫給那些停留在相同心情的人。 丑人MUMMER 不是因為真的醜，而是不願假裝。 活在真相之前，有時顯得不堪，但我們寧願如此。 來自台中的三人樂團。作品有歌詞，也有不靠文字敘述的器樂演奏音樂。用旋律與聲音，記錄與世界的摩擦、與自己的拔河。在越來越追求精緻與完美的年代，我們仍然相信，讓人起雞皮疙瘩的，很多時候不是完美，而是真實。寫給平凡卻不肯被磨平的靈魂。 ———— 🐈‍⬛演出資訊 📆日期與時間：7.12（Sun.) 20:00入場；20:30開演 🧫演出地點：迴響音樂藝文展演空間 🎙️演出陣容：無邊境日常Unlimited Life、凌晨出走Dawn Drift、丑人MUMMER 💿票價：ADV（預售）$400；DOOR（現場）$500 🌀穿隧入口：iNDIEVOX網站 及 全國7-11 ibon系統 *** 本場館全面禁帶外食、敬請見諒 ※本節目由活動主辦建檔上架 ※本平台所售出之活動，除非特別標示，皆無提供履約保障機制。 ※購買票券前，請先了解並同意以上規範，如不同意請勿購買，以免產生不必要之糾紛及損害；當進行購票及退票作業時，將視同您已瞭解並同意遵守以上全部事項。 以下為外部廣告網站，與本公司無關，請審慎點擊廣告連結 深入瞭解 音樂與音訊 音樂 音樂會 嘻哈音樂 音樂活動 節目資訊 獨立音樂 訂單查詢 演唱會門票 現場演出 以上為外部廣告網站，與本公司無關，請審慎點擊廣告連結 | 關於iNDIEVOX | 會員服務條款 | 隱私權政策 | Cookie 偏好設定 | 票務服務單位：一定發股份有限公司／統一編號53550756 客服專線：+886 (02) 8772-6205 客服時間：週一 ~ 週五 13:30-18:00 (適逢國定假日暫停服務) 客服信箱：support@indievox.com © iNDIEVOX 版權所有 當您按下"接受所有 Cookie"，表示您同意我們使用 Cookie 的方式。我們使用 Cookie 以提昇本系統的服務品質、提供個人化內容和廣告、分析使用狀況以協助我們進行行銷工作。 接受所有 Cookie 全部拒絕 Cookie 設定','reviewed',0.45,'????????????????','','2026-06-22T01:36:18.767Z','2026-06-22T01:49:08.167Z','2026-06-22T01:36:23.016Z','2026-06-22T01:49:08.167Z','[]','{}','','legacy');
INSERT INTO "concert_crawl_candidate" ("id","source","source_id","source_kind","title","url","event_at","venue","city","organizer","extracted_text","raw_excerpt","status","confidence","ai_summary","error_message","crawled_at","reviewed_at","created_at","updated_at","evidence_json","source_payload_json","content_hash","parser_version") VALUES(794,'indievox','26_iv0408485','ticket_platform','Wah SUB！010 龐氏騙局; Take This! X Emoment X Butter Riot','https://www.indievox.com/activity/detail/26_iv0408485','2026-07-11T16:00:00.000Z','SUB（台北市南港區市民大道八段99號 / 入口位於臺北流行音樂中心南基地戶外廣場）',NULL,'Take This!、Emoment、Butter Riot','EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 Wah SUB！010 龐氏騙局; Take This! X Emoment X Butter Riot 立即購票 節目介紹 注意事項 演出日期及時間：2026/07/12 (日) 20:00 演出地點：SUB（台北市南港區市民大道八段99號 / 入口位於臺北流行音樂中心南基地戶外廣場） 演出者：Take This!、Emoment、Butter Riot 票價：預售票 800 元 / 身障票 400 元（線上訂購）/ 現場票 1000 元 / 學生優惠雙人套票 1200 元 售票時間：2026/06/15（一）12:00 開始販售 「你不是來聽歌的，你是來成為我們下線的。」 當我在思考要怎麼經營好一個以龐克音樂為主的系列演出時，我突然覺得，發展龐克獨立社群其實跟傳直銷發展組織很類似，於是就請Gemini幫我整理了一下，大家看看，歡迎發表自己的觀點！！！ 節錄開頭： 將龐克社群（Punk Community）與傳直銷營運模式（Multi-Level Marketing, MLM）放在一起比較，乍看之下像把「無政府主義者」和「華爾街商人」關在同一個房間裡，極度魔幻。 但如果我們剝開表面的意識形態（一個極度反資本、一個極度資本主義），從組織行為、群體動力學、信任機制的底層架邏輯來看，會發現這兩者在「建立緊密社群」與「擴散思想/產品」的手段上，竟然有著驚人相似的鏡像關係....... 全文請點此：https://docs.google.com/document/d/14UrAUMMzbFC2FmdoHBRJcOIMqnj_sBOOlWI5PbWOKaU/edit?usp=sharing ※本平台所售出之活動，除非特別標示，皆無提供履約保障機制。 ※購買票券前，請先了解並同意以上規範，如不同意請勿購買，以免產生不必要之糾紛及損害；當進行購票及退票作業時，將視同您已瞭解並同意遵守以上全部事項。 以下為外部廣告網站，與本公司無關，請審慎點擊廣告連結 以上為外部廣告網站，與本公司無關，請審慎點擊廣告連結 | 關於iNDIEVOX | 會員服務條款 | 隱私權政策 | Cookie 偏好設定 | 票務服務單位：一定發股份有限公司／統一編號53550756 客服專線：+886 (02) 8772-6205 客服時間：週一 ~ 週五 13:30-18:00 (適逢國定假日暫停服務) 客服信箱：support@indievox.com © iNDIEVOX 版權所有 當您按下"接受所有 Cookie"，表示您同意我們使用 Cookie 的方式。我們使用 Cookie 以提昇本系統的服務品質、提供個人化內容和廣告、分析使用狀況以協助我們進行行銷工作。 接受所有 Cookie 全部拒絕 Cookie 設定','EN 繁 會員登入／註冊 節目資訊 巡演節目 推薦場館 最新消息 常見問題 訂單查詢 Wah SUB！010 龐氏騙局; Take This! X Emoment X Butter Riot 立即購票 節目介紹 注意事項 演出日期及時間：2026/07/12 (日) 20:00 演出地點：SUB（台北市南港區市民大道八段99號 / 入口位於臺北流行音樂中心南