        ai_reason TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'reviewed',
        last_checked_at TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (STRFTIME('%Y-%m-%dT%H:%M:%fZ','now')),
